Acked-by: Alex Deucher <alexander.deucher@amd.com>
Fixes: ab4750332dbe ("drm/amdgpu/sdma5.2: add begin/end_use ring callbacks")
Signed-off-by: Mario Limonciello <mario.limonciello@amd.com>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>

Here is the root cause:
The bug was caused by the increased usage of GFXOFF control due to changes made in a previous commit, which led to the delayed work for GFXOFF being flushed during the suspend process. This flushing could result in SDMA traffic being triggered while the system was in a suspended state, potentially causing a deadlock when users attempted to suspend the system using GNOME.

Here is the patch:
  */
 int amdgpu_device_suspend(struct drm_device *dev, bool fbcon)
 {
 	struct amdgpu_device *adev = drm_to_adev(dev);
 	int r = 0;

 	if (dev->switch_power_state == DRM_SWITCH_POWER_OFF)
 		return 0;

 	adev->in_suspend = true;

 	if (amdgpu_sriov_vf(adev)) {
 		amdgpu_virt_fini_data_exchange(adev);
 		r = amdgpu_virt_request_full_gpu(adev, false);
 		if (r)
 			return r;
 	}

 	if (amdgpu_acpi_smart_shift_update(dev, AMDGPU_SS_DEV_D3))
 		DRM_WARN("smart shift update failed\n");

 	if (fbcon)
 		drm_fb_helper_set_suspend_unlocked(adev_to_drm(adev)->fb_helper, true);

 	cancel_delayed_work_sync(&adev->delayed_init_work);
-	flush_delayed_work(&adev->gfx.gfx_off_delay_work);

 	amdgpu_ras_suspend(adev);

 	amdgpu_device_ip_suspend_phase1(adev);

 	if (!adev->in_s0ix)
 		amdgpu_amdkfd_suspend(adev, adev->in_runpm);

 	r = amdgpu_device_evict_resources(adev);
 	if (r)
 		return r;

 	amdgpu_ttm_set_buffer_funcs_status(adev, false);

 	amdgpu_fence_driver_hw_fini(adev);

 	amdgpu_device_ip_suspend_phase2(adev);

 	if (amdgpu_sriov_vf(adev))
 		amdgpu_virt_release_full_gpu(adev, false);

 	r = amdgpu_dpm_notify_rlc_state(adev, false);
 	if (r)
 		return r;

 	return 0;
 }



